import json
import math
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ValueError("invalid JSON") from e
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data

def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    data = payloads[0]
    if isinstance(data, dict) and set(data) == {"name", "result"}:
        data = data["result"]

    contacts = data["contacts"]
    self_id = data["self_id"]
    keyword = data["keyword"]
    emails = data["emails"]

    contact_ids = {c["id"] for c in contacts}
    if self_id not in contact_ids:
        raise ValueError("unknown self_id")

    ids = set()
    for e in emails:
        sender = e["sender"]
        if sender not in contact_ids:
            raise ValueError("unknown sender")
        if sender == self_id:
            continue
        if keyword.casefold() in e["subject"].casefold():
            ids.add(sender)

    return {"name": contract["name"], "result": {"ids": sorted(ids)}}

