import json
import math
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ValueError("invalid JSON") from e
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data

def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    snapshot = _unwrap(payloads[0])
    groups = _unwrap(payloads[1])
    mail = _unwrap(payloads[2])
    calendar = _unwrap(payloads[3])

    contacts = snapshot["contacts"]
    ages = {c["id"]: c["age"] for c in contacts}

    candidate_ids = set(groups["ids"]) | set(mail["ids"])
    minutes_map = calendar["minutes"]

    # Union of candidates; minutes default to 0 for candidates not in calendar.
    rows = []
    for cid in candidate_ids:
        if cid not in ages:
            raise ValueError("unknown contact id")
        minutes = minutes_map.get(cid, 0)
        rows.append({"id": cid, "minutes": minutes, "age": ages[cid]})

    rows.sort(key=lambda r: (-r["minutes"], -r["age"], r["id"]))

    winner = rows[0]["id"] if rows else None
    return {"name": contract["name"], "result": {"ranking": rows, "winner": winner}}

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _load_contracts():
    contracts = []
    for cp in sorted(ROOT.rglob('contract.json')):
        if 'outputs' in cp.relative_to(ROOT).parts:
            continue
        contracts.append(cp)
    if not contracts:
        raise ValueError('no contracts')
    return contracts


def _topological_order(contracts):
    # Build dependency graph keyed by component name.
    by_name = {}
    for cp in contracts:
        c = json.loads(cp.read_text(encoding='utf-8'))
        by_name[c['name']] = (cp, c)

    # Map output path -> producing component name.
    producer = {}
    for name, (cp, c) in by_name.items():
        producer[c['output']] = name

    # Build edges: component depends on components that produce its inputs.
    deps = {}
    for name, (cp, c) in by_name.items():
        d = set()
        for inp in c['inputs']:
            if inp in producer:
                d.add(producer[inp])
        deps[name] = d

    # Kahn's algorithm.
    order = []
    remaining = set(by_name)
    while remaining:
        ready = [n for n in remaining if deps[n] <= set(order)]
        if not ready:
            raise ValueError('dependency cycle detected')
        ready.sort()
        for n in ready:
            order.append(n)
            remaining.discard(n)
    return [by_name[n][0] for n in order]


def main():
    contracts = _load_contracts()
    ordered = _topological_order(contracts)
    for cp in ordered:
        subprocess.run(
            [sys.executable, str(cp.with_name('render.py'))],
            cwd=ROOT,
            check=True,
        )
    subprocess.run(
        [sys.executable, str(ROOT / 'integrate.py')],
        cwd=ROOT,
        check=True,
    )
    subprocess.run(
        [sys.executable, str(ROOT / 'final_report.py')],
        cwd=ROOT,
        check=True,
    )


if __name__ == '__main__':
    main()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _attention(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get('blocked') is True:
            names.append(name)
            continue
        for key in ('complete', 'checkout', 'committed', 'ok'):
            if result.get(key) is False:
                names.append(name)
                break
        else:
            for key in ('unavailable', 'missing', 'conflicts', 'unreachable'):
                v = result.get(key)
                if isinstance(v, (list, dict, str, tuple)) and len(v) > 0:
                    names.append(name)
                    break
    return sorted(set(names))


def main():
    core_path = ROOT / 'outputs' / 'core_manifest.json'
    core = json.loads(core_path.read_text(encoding='utf-8'))
    components = core['components']

    serialized = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(',', ':'),
        allow_nan=False,
    ).encode('utf-8')
    sha = hashlib.sha256(serialized).hexdigest()

    report = {
        'title': '跨应用候选并集与相处时长排名',
        'component_count': len(components),
        'sha256': sha,
        'attention': _attention(components),
    }

    out = ROOT / 'outputs' / 'final_report.json'
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + '\n',
        encoding='utf-8',
    )


if __name__ == '__main__':
    main()

