class TestRanking(unittest.TestCase):
    def test_union_and_sort(self):
        snapshot = {
            "contacts": [
                {"id": "self", "age": 20},
                {"id": "a", "age": 30},
                {"id": "b", "age": 25},
                {"id": "c", "age": 40},
            ]
        }
        groups = {"ids": ["a", "b"]}
        mail = {"ids": ["b", "c"]}
        calendar = {"minutes": {"a": 10, "b": 50, "c": 50}}
        contract = {"name": "ranking", "inputs": ["x", "y", "z", "w"]}
        result = transform([snapshot, groups, mail, calendar], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "ranking")
        r = result["result"]
        # union = {a,b,c}; sort by minutes desc, age desc, id asc
        self.assertEqual(
            [row["id"] for row in r["ranking"]], ["c", "b", "a"]
        )
        self.assertEqual(r["winner"], "c")
        self.assertEqual(r["ranking"][0], {"id": "c", "minutes": 50, "age": 40})

    def test_empty_union(self):
        snapshot = {"contacts": [{"id": "self", "age": 20}]}
        contract = {"name": "ranking", "inputs": ["x", "y", "z", "w"]}
        result = transform(
            [snapshot, {"ids": []}, {"ids": []}, {"minutes": {}}], contract
        )
        self.assertEqual(result["result"]["ranking"], [])
        self.assertIsNone(result["result"]["winner"])

