            if a == self_id or a in seen:
                continue
            seen.add(a)
            if a not in contact_ids:
                raise ValueError("unknown attendee")
            minutes[a] = minutes.get(a, 0) + duration

    return {"name": contract["name"], "result": {"minutes": minutes}}
